//! The bodies of the dc-kt3l acceptance cases (the `#[test]` functions sit at the root of
//! `tests/acceptance.rs`, so libtest lists them under their registered names). Both drive the
//! xtask binary this test build compiled (`CARGO_BIN_EXE_xtask`), the binary `cargo xtask compare`
//! runs, on a macro-enabled workbook package (`.xlsm`, with no VBA project) generated byte for byte
//! (`dc_kt3l_package.rs`).
//!
//! The workbook: sheet Inputs holds A1 = 1.5, A2 = 2.25 and A3 = 4; sheet Calc holds a SUM chain,
//! a formula whose cached result is deliberately wrong, a function no catalogue holds and a reader
//! of it:
//!
//! | Calc | formula                    | cached in the package | Excel's value (hand-derived)   |
//! |------|----------------------------|-----------------------|--------------------------------|
//! | A1   | `SUM(Inputs!A1:A3)`        | 7.75                  | 1.5 + 2.25 + 4 = 7.75          |
//! | A2   | `SUM(A1,Inputs!A1)`        | 9.25                  | 7.75 + 1.5 = 9.25              |
//! | A3   | `SUM(A1:A2)`               | 99 (wrong)            | 7.75 + 9.25 = 17               |
//! | B1   | `NOSUCHFUNCTION(Inputs!A1)`| #NAME?                | #NAME? (no function or VBA project holds the name) |
//! | B2   | `B1*2`                     | #NAME?                | #NAME? (B1's error passes through)|
//!
//! Every sum is exact in binary64, so the hand-derived values are exact. B1 names no function
//! Excel or calc-func knows, so it stays not modelled as calc-func gains functions. In a workbook
//! without macros CalcFml would give B1 Excel's #NAME? (dc-m3u); in this macro-enabled one a VBA
//! function could hold the name, and CalcFml cannot see VBA, so it refuses the call and B1 is a
//! function-missing root. Being refused, B1 never matches its #NAME? expectation and counts as
//! not modelled.
//!
//! `dc_kt3l__every_cell_classified` (windows, linux) compares the workbook with capture records
//! authored in this test; no Excel runs, and the case says so in an `ACCEPT-NOTE`. Their
//! observations are the hand-derived values above, labelled in the record as caches of unknown
//! freshness of a file-cache replay (the record has no kind for authored expectations; they were
//! neither read from this package, whose A3 caches 99, nor observed in Excel). Every inventory
//! cell must get exactly one class (A1 to A3 matched, B1 a function-missing root keyed
//! NOSUCHFUNCTION, B2 reading that root), A3 must be matched by the value its evaluation returned
//! (17), never by its cache, no cache may score, and B2's not-modelled provenance in `report.json`
//! must name its typed refusal and the cell it read. Then:
//!
//! - a capture whose A3 expectation is 17.000000000000004, one ulp above 17 and authored to differ
//!   (not an Excel value), must class A3 kernel-bits under SUM with SUM's FunctionId, the values
//!   its read of Calc!A1:A2 was shown (7.75 and 9.25), both values' bits, an ulp distance of 1 and
//!   agreement to 15 significant digits: the triage reached through the evaluations the read
//!   observer kept;
//! - a version 2 capture naming the 1904 date system, and a version 1 capture of a package that
//!   declares it (which the host does not apply), must class the calculated cells context;
//! - a variant with a circular reference (Calc!C1 = C1+1) and iteration off: since dc-m3u the
//!   engine refuses the formula on the cycle, not the recalculation, so C1 must be a typed
//!   not-modelled root (no Excel value is authored for it: the capture leaves it unobserved) and
//!   every other cell must be classed as in the workbook without C1, A3 matched by the 17 its
//!   evaluation returned and C1 never evaluated;
//! - a variant calc-doc refuses (an ISO date cell, `t="d"`) must class every cell doc under the
//!   load error;
//! - a run under `--exact-target` must recalculate under that Exact mode (the evaluator refuses SUM
//!   with `ExactUnavailable`, calc-func having no Exact arithmetic yet), keyed apart from a missing
//!   function;
//! - a capture of other bytes must be refused with nothing written.
//!
//! A recalculation that fails after evaluations were recorded is `cargo xtask compare`'s unit test
//! `a_recalculation_failing_after_evaluations_drops_them` (`cargo test -p xtask --bins`, a command
//! the bead registers): no workbook makes the product's own observer stop a recalculation, and
//! since dc-m3u no workbook makes the engine refuse one (a cycle refuses only its formulas).
//!
//! `dc_kt3l__live_capture` (excel) captures the same workbook live on this machine through
//! `cargo xtask capture` and compares it: Excel's raw values must equal the hand-derived ones and
//! the classes must be those above. It starts Excel only on the excel route
//! (`DNACALC_ACCEPT_PLATFORM=excel`), and prints `ACCEPT-NOT-RUN` only when this host cannot run a
//! capture (exit 4) or the capture was refused for its Excel instance's isolation; any other
//! capture failure fails the case.
//!
//! Evidence goes to `target/accept/dc-kt3l/<case>/`.

use calc_verdict::{CalculationContext, CaptureRecord, CaptureSession, sha256_hex};
use serde_json::{Value, json};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

#[path = "dc_kt3l_package.rs"]
mod package;

use package::{calc_sheet, inputs_sheet, package, package_with, workbook};

const BEAD: &str = "dc-kt3l";
const CLASSIFIED: &str = "dc_kt3l__every_cell_classified";
const LIVE: &str = "dc_kt3l__live_capture";

/// The variable the acceptance runner sets to the platform route a case runs on.
const PLATFORM_VARIABLE: &str = "DNACALC_ACCEPT_PLATFORM";

/// Checks the bead's registration: exactly the two cases, each on its platforms.
fn registered(case: &str) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("acceptance.json");
    let manifest = super::read_json(&path);
    let entry = manifest["beads"]
        .as_array()
        .and_then(|beads| beads.iter().find(|bead| bead["id"] == BEAD))
        .unwrap_or_else(|| panic!("{} has no entry for {BEAD}", path.display()));
    assert_eq!(
        super::strings(&entry["cases"], "registered cases"),
        [CLASSIFIED, LIVE],
        "{BEAD} must register exactly its two cases"
    );
    assert!(
        super::strings(&entry["cases"], "registered cases")
            .iter()
            .any(|registered| registered == case)
    );
    assert_eq!(
        super::strings(&entry["platforms"][CLASSIFIED], "platforms"),
        ["windows", "linux"]
    );
    assert_eq!(
        super::strings(&entry["platforms"][LIVE], "platforms"),
        ["excel"]
    );
}

/// A cleared evidence directory for `case`.
fn evidence_dir(case: &str) -> PathBuf {
    let dir = super::repo_root()
        .join("target")
        .join("accept")
        .join(BEAD)
        .join(case);
    if dir.exists() {
        fs::remove_dir_all(&dir).unwrap_or_else(|e| panic!("cannot clear {}: {e}", dir.display()));
    }
    fs::create_dir_all(&dir).unwrap_or_else(|e| panic!("cannot create {}: {e}", dir.display()));
    dir
}

// ---------------------------------------------------------------------------------------------
// The authored captures

/// The hand-derived Excel value of each Calc formula cell, as a cache of `t` and `v` text: the
/// module documentation's last column.
const HAND_DERIVED: [(&str, u32, u32, &str, &str); 5] = [
    ("Calc", 1, 1, "n", "7.75"),
    ("Calc", 2, 1, "n", "9.25"),
    ("Calc", 3, 1, "n", "17"),
    ("Calc", 1, 2, "e", "#NAME?"),
    ("Calc", 2, 2, "e", "#NAME?"),
];

/// [`HAND_DERIVED`] with A3's expectation one ulp above 17: authored to differ from what SUM
/// returns, not a value Excel gave.
const ONE_ULP_ABOVE: [(&str, u32, u32, &str, &str); 5] = [
    ("Calc", 1, 1, "n", "7.75"),
    ("Calc", 2, 1, "n", "9.25"),
    ("Calc", 3, 1, "n", "17.000000000000004"),
    ("Calc", 1, 2, "e", "#NAME?"),
    ("Calc", 2, 2, "e", "#NAME?"),
];

/// A version 1 capture record of `package`'s bytes listing the Calc formula cells of `values`
/// plus `unobserved` (row, column) cells without an observation. The observations are `values`,
/// written as caches of unknown freshness of a file-cache replay: no Excel observed them and this
/// package does not cache all of them.
fn authored_capture(
    package: &[u8],
    values: &[(&str, u32, u32, &str, &str)],
    unobserved: &[(u32, u32)],
) -> String {
    let mut formulas: Vec<String> = values
        .iter()
        .map(|(sheet, row, column, _, _)| {
            format!(
                r#"{{"sheet": "{sheet}", "row": {row}, "column": {column}, "kind": "ordinary"}}"#
            )
        })
        .collect();
    formulas.extend(unobserved.iter().map(|(row, column)| {
        format!(r#"{{"sheet": "Calc", "row": {row}, "column": {column}, "kind": "ordinary"}}"#)
    }));
    let observations: Vec<String> = values
        .iter()
        .map(|(sheet, row, column, t, v)| {
            format!(
                r#"{{"sheet": "{sheet}", "row": {row}, "column": {column}, "unknown_freshness_cache": {{"t": "{t}", "v": "{v}"}}}}"#
            )
        })
        .collect();
    format!(
        "{{\"format\": \"dnacalc-capture-record\", \"version\": 1, \"case\": \"{CLASSIFIED}\", \"source\": \"sha256:{}\",\n \"acquisition\": {{\"kind\": \"file_cache_replay\"}}, \"environment\": null,\n \"sheets\": [{{\"name\": \"Inputs\", \"visibility\": \"visible\"}}, {{\"name\": \"Calc\", \"visibility\": \"visible\"}}],\n \"formulas\": [{}],\n \"observations\": [{}]}}\n",
        sha256_hex(package),
        formulas.join(", "),
        observations.join(", ")
    )
}

/// The version 2 form of the authored capture `version_1`, its session naming the calculation
/// context `context` at revision 0 and no capture tool (none ran).
fn with_session(version_1: &str, context: &str) -> String {
    let mut record = CaptureRecord::decode(version_1.as_bytes())
        .unwrap_or_else(|e| panic!("the authored capture does not decode: {e}"));
    record.session = Some(CaptureSession {
        revision: 0,
        operations: Vec::new(),
        context: context.to_owned(),
        tool: format!("none: authored in {CLASSIFIED}"),
        input_package: record.source.clone(),
        output_package: None,
        failures: Vec::new(),
        shared_ranges: Vec::new(),
        saved: Vec::new(),
        reopened: Vec::new(),
    });
    record
        .encode()
        .unwrap_or_else(|e| panic!("the authored version 2 capture does not encode: {e}"))
}

// ---------------------------------------------------------------------------------------------
// Running the command and reading what it wrote

/// `cargo xtask <args>` through the binary this test build compiled, from the repository root,
/// recorded under `dir` as `<label>.*`.
fn xtask(label: &str, args: &[&str], dir: &Path) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_xtask"));
    command.args(args).current_dir(super::repo_root());
    super::run_recorded(label, command, dir)
}

/// Runs `cargo xtask compare` on `fixture` and `capture` with `out` as the output directory.
fn compare(label: &str, fixture: &Path, capture: &Path, out: &Path, dir: &Path) -> Output {
    xtask(
        label,
        &[
            "compare",
            "--fixture",
            &fixture.display().to_string(),
            "--capture",
            &capture.display().to_string(),
            "--out",
            &out.display().to_string(),
        ],
        dir,
    )
}

/// Writes `package` and the capture `capture_text` as `<label>.xlsm` and `<label>-capture.json`
/// under `dir`, compares them into `<label>/`, and returns the output directory and what the
/// command printed, or records a failure when it did not exit 0.
fn compared(
    label: &str,
    package: &[u8],
    capture_text: &str,
    dir: &Path,
    failures: &mut Vec<String>,
) -> Option<(PathBuf, Output)> {
    let fixture = dir.join(format!("{label}.xlsm"));
    super::write(&fixture, package);
    let capture = dir.join(format!("{label}-capture.json"));
    super::write(&capture, capture_text);
    let out = dir.join(label);
    let output = compare(label, &fixture, &capture, &out, dir);
    if output.status.code() == Some(0) {
        Some((out, output))
    } else {
        failures.push(format!(
            "cargo xtask compare ({label}) exited {:?}: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stderr)
        ));
        None
    }
}

/// The cells of `triage` as `<sheet>!<cell> <verdict> <class> <key> <role>[ root=<cell>][
/// blocks=<n>]`, in the inventory's order.
fn triaged(triage: &Value) -> Vec<String> {
    triage["cells"]
        .as_array()
        .expect("triage.json lists its cells")
        .iter()
        .map(|cell| {
            let mut line = format!(
                "{}!{} {} {} {} {}",
                cell["sheet"].as_str().unwrap(),
                cell["cell"].as_str().unwrap(),
                cell["verdict"].as_str().unwrap(),
                cell["class"].as_str().unwrap(),
                cell["key"].as_str().unwrap(),
                cell["role"].as_str().unwrap_or("-")
            );
            if let Some(root) = cell["root"].as_str() {
                line.push_str(&format!(" root={root}"));
            }
            if let Some(blocks) = cell["blocks"].as_u64() {
                line.push_str(&format!(" blocks={blocks}"));
            }
            line
        })
        .collect()
}

/// The classes `triage.json` may give a cell.
const CLASSES: [&str; 10] = [
    "matched",
    "kernel-value",
    "kernel-bits",
    "formula",
    "function-missing",
    "not-modelled",
    "engine",
    "context",
    "doc",
    "capture",
];

/// Checks that `triage` lists every formula cell of `capture`'s inventory exactly once, each with
/// one of the ten classes and a key, and that its class counts add up to the inventory.
fn every_cell_once(triage: &Value, capture: &Value, failures: &mut Vec<String>) {
    let inventory: Vec<String> = capture["formulas"]
        .as_array()
        .unwrap()
        .iter()
        .map(|cell| format!("{} {} {}", cell["sheet"], cell["row"], cell["column"]))
        .collect();
    let listed: Vec<String> = triage["cells"]
        .as_array()
        .unwrap()
        .iter()
        .map(|cell| format!("{} {} {}", cell["sheet"], cell["row"], cell["column"]))
        .collect();
    if listed != inventory {
        failures.push(format!(
            "triage.json lists {listed:?}, not the inventory {inventory:?} once each in order"
        ));
    }
    for cell in triage["cells"].as_array().unwrap() {
        let class = cell["class"].as_str().unwrap_or_default();
        if !CLASSES.contains(&class) || cell["key"].as_str().is_none_or(str::is_empty) {
            failures.push(format!("a cell has no class of the ten or no key: {cell}"));
        }
    }
    let counted: u64 = triage["classes"]
        .as_object()
        .unwrap()
        .values()
        .map(|count| count["cells"].as_u64().unwrap())
        .sum();
    if counted != inventory.len() as u64 || triage["inventory"] != inventory.len() {
        failures.push(format!(
            "the class counts add up to {counted}, and triage.json's inventory is {}, for {} inventory cells",
            triage["inventory"],
            inventory.len()
        ));
    }
}

/// `(denominator, calculated, matched, mismatched, file_cached, stale, not_modeled, missing,
/// not_calculated_equal_to_expectation, evaluator_calls)` of a report.
fn counts(report: &Value) -> [u64; 10] {
    let c = &report["counts"];
    [
        "denominator",
        "calculated",
        "matched",
        "mismatched",
        "file_cached",
        "stale",
        "not_modeled",
        "missing",
        "not_calculated_equal_to_expectation",
        "evaluator_calls",
    ]
    .map(|name| {
        c[name]
            .as_u64()
            .unwrap_or_else(|| panic!("the report has no count {name}"))
    })
}

/// Each evaluation of `evaluations` as `<sheet>!R<row>C<column> <returned>`.
fn evaluated(evaluations: &Value) -> Vec<String> {
    evaluations["evaluations"]
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| {
            let returned = &entry["returned"];
            let returned = if let Some(value) = returned.get("value") {
                value.to_string()
            } else {
                "no_value".to_owned()
            };
            format!(
                "{}!R{}C{} {returned}",
                entry["sheet"].as_str().unwrap(),
                entry["row"],
                entry["column"]
            )
        })
        .collect()
}

/// The report's cell `<sheet>!<a1>`.
fn report_cell<'r>(report: &'r Value, sheet: &str, a1: &str) -> &'r Value {
    report["cells"]
        .as_array()
        .unwrap()
        .iter()
        .find(|cell| cell["sheet"] == sheet && cell["cell"] == a1)
        .unwrap_or_else(|| panic!("the report has no cell {sheet}!{a1}"))
}

/// The classes of B1 and B2 when the workbook calculates: a function-missing root and its reader.
const CLASSES_B: [&str; 2] = [
    "Calc!B1 not_modeled function-missing NOSUCHFUNCTION root blocks=1",
    "Calc!B2 not_modeled function-missing NOSUCHFUNCTION reads_root root=Calc!B1",
];

/// The classes of the workbook's five cells when it calculates: the SUM chain matched, B1 a
/// function-missing root and B2 reading it.
const CLASSES_CALCULATED: [&str; 5] = [
    "Calc!A1 matched matched matched -",
    "Calc!A2 matched matched matched -",
    "Calc!A3 matched matched matched -",
    CLASSES_B[0],
    CLASSES_B[1],
];

/// The not-modelled features `report.json` must name: each cell's typed refusal and what it
/// concerns, B2's naming the inventory cell it read (never the triage key of a read outside the
/// inventory).
const FEATURES: [(&str, &str); 2] = [
    ("B1", "Compile:UnknownFunction (NOSUCHFUNCTION)"),
    ("B2", "Evaluation:MissingInput (reads Calc!B1)"),
];

/// Checks the features of B1 and B2 in `report`.
fn check_features(report: &Value, label: &str, failures: &mut Vec<String>) {
    for (a1, feature) in FEATURES {
        let cell = report_cell(report, "Calc", a1);
        if cell["verdict"] != "not_modeled" || cell["feature"] != feature {
            failures.push(format!(
                "{label}: Calc!{a1}'s report entry is {cell}, expected not_modeled with feature {feature:?}"
            ));
        }
    }
}

/// The checks the calculated workbook's compare must pass, whatever its capture: every cell once,
/// the five classes, A3 matched by the 17 its evaluation returned, B1's and B2's features, and the
/// summary's lines.
fn check_calculated(
    out: &Path,
    output: &Output,
    capture: &Value,
    evidence: &mut Vec<String>,
    failures: &mut Vec<String>,
) {
    let triage = super::read_json(&out.join("triage.json"));
    let report = super::read_json(&out.join("report.json"));
    let evaluations = super::read_json(&out.join("evaluations.json"));
    every_cell_once(&triage, capture, failures);
    let classes = triaged(&triage);
    if classes != CLASSES_CALCULATED {
        failures.push(format!(
            "the cells are classed {classes:?}, expected {CLASSES_CALCULATED:?}"
        ));
    }
    evidence.push(format!("classes: {classes:?}"));
    // The report: three calculated and matched, two not modelled, and no value that was not
    // calculated equals its expectation (no cache was scored or even compared).
    let counted = counts(&report);
    if counted != [5, 3, 3, 0, 0, 0, 2, 0, 0, 4] {
        failures.push(format!(
            "report counts (denominator, calculated, matched, mismatched, file_cached, stale, not_modeled, missing, not_calculated_equal_to_expectation, evaluator_calls) are {counted:?}, expected [5, 3, 3, 0, 0, 0, 2, 0, 0, 4]"
        ));
    }
    evidence.push(format!("report counts: {counted:?}"));
    check_features(&report, "the calculated workbook", failures);
    evidence.push(format!(
        "report features: Calc!B1 {}, Calc!B2 {}",
        report_cell(&report, "Calc", "B1")["feature"],
        report_cell(&report, "Calc", "B2")["feature"]
    ));
    // The evaluation record is version 2 and its evaluation of A3 returned 17 (bits
    // 4031000000000000), not the cached 99: the matched verdict rests on that value. B1 was not
    // compiled, so it was not evaluated; B2's evaluation stopped at B1 and returned no value. The
    // evaluations are compared in cell order, whatever order the engine ran them in.
    let mut returned = evaluated(&evaluations);
    returned.sort();
    let expected_returned = [
        r#"Calc!R1C1 {"number":"401f000000000000"}"#,
        r#"Calc!R2C1 {"number":"4022800000000000"}"#,
        "Calc!R2C2 no_value",
        r#"Calc!R3C1 {"number":"4031000000000000"}"#,
    ];
    if evaluations["version"] != 2 || returned != expected_returned {
        failures.push(format!(
            "the evaluation record (version {}) holds {returned:?}, expected {expected_returned:?}",
            evaluations["version"]
        ));
    }
    evidence.push(format!("evaluations: {returned:?}"));
    let a3 = report_cell(&report, "Calc", "A3");
    if a3["verdict"] != "matched" || a3.get("value_equals_expectation").is_some() {
        failures.push(format!("Calc!A3's verdict is {a3}"));
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in [
        "xtask compare: dc_kt3l__",
        "inventory 5 formula cells; calculated 3; matched 3; mismatched 0;",
        "xtask compare: classes: matched 3, function-missing 2 (1 root, 1 reading a root)",
        "xtask compare: mismatched by class: none",
        "xtask compare:   function-missing NOSUCHFUNCTION: 1 root, blocking 1 cell: Calc!B1 blocks 1",
        "xtask compare: wall time: open ",
    ] {
        if !stdout.contains(line) {
            failures.push(format!("the summary has no line with {line:?}:\n{stdout}"));
        }
    }
}

/// The kernel-bits run: A3's authored expectation is one ulp above the 17 SUM returns, so A3 is a
/// kernel-bits root under SUM, carrying SUM's FunctionId, the values its read of Calc!A1:A2 was
/// shown, both values' bits, the ulp distance and the agreement to 15 significant digits.
fn check_kernel_bits(
    out: &Path,
    output: &Output,
    capture: &Value,
    evidence: &mut Vec<String>,
    failures: &mut Vec<String>,
) {
    let triage = super::read_json(&out.join("triage.json"));
    let report = super::read_json(&out.join("report.json"));
    every_cell_once(&triage, capture, failures);
    let classes = triaged(&triage);
    let expected = [
        "Calc!A1 matched matched matched -",
        "Calc!A2 matched matched matched -",
        "Calc!A3 mismatched kernel-bits SUM root",
        CLASSES_B[0],
        CLASSES_B[1],
    ];
    if classes != expected {
        failures.push(format!(
            "the kernel-bits run's cells are classed {classes:?}, expected {expected:?}"
        ));
    }
    let counted = counts(&report);
    if counted != [5, 3, 2, 1, 0, 0, 2, 0, 0, 4] {
        failures.push(format!(
            "the kernel-bits run's report counts are {counted:?}, expected [5, 3, 2, 1, 0, 0, 2, 0, 0, 4]"
        ));
    }
    let sum = calc_func::catalogue()
        .targets()
        .find(|target| target.spelling() == "SUM")
        .expect("the catalogue holds SUM")
        .id();
    let difference = &triage["cells"][2]["difference"];
    let expected_difference = json!({
        "function": {
            "id": format!("{sum:?}"),
            "raw": sum.raw(),
            "spelling": "SUM",
            "notation": "Call",
            "synthetic": false,
        },
        "calls": [{
            "id": format!("{sum:?}"),
            "raw": sum.raw(),
            "spelling": "SUM",
            "notation": "Call",
            "synthetic": false,
        }],
        "reads": [{
            "area": "Calc!A1:A2",
            "cells": 2,
            "runs": [
                {"number": "401f000000000000", "decimal": "7.75"},
                {"number": "4022800000000000", "decimal": "9.25"},
            ],
            "omitted_cells": 0,
        }],
        "expected": {"number": "4031000000000001", "decimal": "17.000000000000004"},
        "actual": {"number": "4031000000000000", "decimal": "17.0"},
        "ulp": 1,
        "agrees_to_15_significant_digits": true,
        "expected_15": "1.70000000000000e1",
        "actual_15": "1.70000000000000e1",
    });
    if *difference != expected_difference {
        failures.push(format!(
            "the kernel-bits run's Calc!A3 difference is {difference}, expected {expected_difference}"
        ));
    }
    if triage["run"]["evaluations_kept_with_reads"] != 1 {
        failures.push(format!(
            "the kernel-bits run kept {} evaluations with their reads, expected 1",
            triage["run"]["evaluations_kept_with_reads"]
        ));
    }
    if triage["attribution"]["kernel_function"]
        .as_str()
        .is_none_or(|text| !text.starts_with("inferred:"))
    {
        failures.push(format!(
            "triage.json does not say the kernel attribution is inferred: {}",
            triage["attribution"]
        ));
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in [
        "inventory 5 formula cells; calculated 3; matched 2; mismatched 1;",
        "xtask compare: mismatched by class: kernel-bits 1",
    ] {
        if !stdout.contains(line) {
            failures.push(format!(
                "the kernel-bits run's summary has no line with {line:?}:\n{stdout}"
            ));
        }
    }
    evidence.push(format!(
        "kernel-bits run (A3 expected 17.000000000000004, authored): classes {classes:?}; report counts {counted:?}; Calc!A3 difference {difference}"
    ));
}

/// The body of `dc_kt3l__every_cell_classified`.
pub(super) fn every_cell_classified() {
    registered(CLASSIFIED);
    println!(
        "ACCEPT-NOTE: {CLASSIFIED}: the capture records are authored in the case: their observations are hand-derived values (Calc!A1 7.75, A2 9.25, A3 17, B1 and B2 #NAME?) labelled as caches of unknown freshness of a file-cache replay, and the kernel-bits run's A3 expectation 17.000000000000004 is authored to differ, not an Excel value; no Excel ran"
    );
    let dir = evidence_dir(CLASSIFIED);
    let mut evidence = Vec::new();
    let mut failures = Vec::new();

    // 1. The workbook and its authored capture.
    let book = workbook();
    let fixture = dir.join("workbook.xlsm");
    super::write(&fixture, &book);
    let capture_text = authored_capture(&book, &HAND_DERIVED, &[]);
    let capture_path = dir.join("capture.json");
    super::write(&capture_path, &capture_text);
    let capture: Value = serde_json::from_str(&capture_text).unwrap();
    let out = dir.join("compare");
    let output = compare("compare", &fixture, &capture_path, &out, &dir);
    if output.status.code() != Some(0) {
        failures.push(format!(
            "cargo xtask compare exited {:?}: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stderr)
        ));
    } else {
        check_calculated(&out, &output, &capture, &mut evidence, &mut failures);
    }

    // 2. A3's expectation authored one ulp above 17: a kernel-bits root under SUM, reached through
    // the calls and reads the read observer kept of A3's evaluation.
    let kernel_text = authored_capture(&book, &ONE_ULP_ABOVE, &[]);
    if let Some((out, output)) = compared(
        "compare-kernel-bits",
        &book,
        &kernel_text,
        &dir,
        &mut failures,
    ) {
        check_kernel_bits(
            &out,
            &output,
            &serde_json::from_str(&kernel_text).unwrap(),
            &mut evidence,
            &mut failures,
        );
    }

    // 3. Context. A version 2 capture whose session names the 1904 date system: judge finds the
    // calculated cells calculated under another context than the capture's, and the triage
    // classes them context under the setting that differs.
    let date1904 = CalculationContext::without_iteration(true, false).fingerprint();
    let v2_text = with_session(&capture_text, &date1904);
    if let Some((out, _)) = compared("compare-context-v2", &book, &v2_text, &dir, &mut failures) {
        let triage = super::read_json(&out.join("triage.json"));
        let report = super::read_json(&out.join("report.json"));
        every_cell_once(
            &triage,
            &serde_json::from_str(&v2_text).unwrap(),
            &mut failures,
        );
        let classes = triaged(&triage);
        let key = "date1904: capture true, run false";
        let expected = [
            format!("Calc!A1 stale context {key} workbook"),
            format!("Calc!A2 stale context {key} workbook"),
            format!("Calc!A3 stale context {key} workbook"),
            CLASSES_B[0].to_owned(),
            CLASSES_B[1].to_owned(),
        ];
        if classes != expected {
            failures.push(format!(
                "the version 2 context run's cells are classed {classes:?}, expected {expected:?}"
            ));
        }
        if counts(&report)[..4] != [5, 0, 0, 0] || report["captured"]["context"] != date1904 {
            failures.push(format!(
                "the version 2 context run's report counts are {:?} and its captured context {}",
                counts(&report),
                report["captured"]
            ));
        }
        evidence.push(format!(
            "version 2 capture naming date1904=true: classes {classes:?}"
        ));
    }
    // A version 1 capture of a package declaring the 1904 date system, which the host does not
    // apply: judge has no captured context to compare, and the triage classes the calculated
    // cells context under the declaration, matched or not.
    let declared = package_with(
        &inputs_sheet(""),
        &calc_sheet(""),
        r#"<workbookPr date1904="1"/>"#,
    );
    let declared_text = authored_capture(&declared, &HAND_DERIVED, &[]);
    if let Some((out, output)) = compared(
        "compare-context-declared",
        &declared,
        &declared_text,
        &dir,
        &mut failures,
    ) {
        let triage = super::read_json(&out.join("triage.json"));
        every_cell_once(
            &triage,
            &serde_json::from_str(&declared_text).unwrap(),
            &mut failures,
        );
        let classes = triaged(&triage);
        let key = "date1904: package declares true, run applies false (the version 1 capture names no context)";
        let expected = [
            format!("Calc!A1 matched context {key} workbook"),
            format!("Calc!A2 matched context {key} workbook"),
            format!("Calc!A3 matched context {key} workbook"),
            CLASSES_B[0].to_owned(),
            CLASSES_B[1].to_owned(),
        ];
        let stdout = String::from_utf8_lossy(&output.stdout);
        if classes != expected
            || triage["run"]["declared_context_not_applied"] != key
            || !stdout.contains("the package declares a context the run does not apply")
        {
            failures.push(format!(
                "the declared-context run's cells are classed {classes:?} (expected {expected:?}), its run member is {}, and its summary is\n{stdout}",
                triage["run"]
            ));
        }
        evidence.push(format!(
            "version 1 capture of a package declaring date1904: classes {classes:?}"
        ));
    }

    // 4. The variant with a circular reference and iteration off: the engine refuses C1, the
    // formula on the cycle, and calculates the rest, so the other five cells are classed as in
    // the workbook without C1 and C1, unobserved in the capture, is a typed not-modelled root.
    let cyclic = package(
        &inputs_sheet(""),
        &calc_sheet(r#"<c r="C1"><f>C1+1</f></c>"#),
    );
    let cyclic_fixture = dir.join("cyclic.xlsm");
    super::write(&cyclic_fixture, &cyclic);
    let cyclic_text = authored_capture(&cyclic, &HAND_DERIVED, &[(1, 3)]);
    let cyclic_capture = dir.join("cyclic-capture.json");
    super::write(&cyclic_capture, &cyclic_text);
    let cyclic_out = dir.join("compare-cyclic");
    let output = compare(
        "compare-cyclic",
        &cyclic_fixture,
        &cyclic_capture,
        &cyclic_out,
        &dir,
    );
    if output.status.code() != Some(0) {
        failures.push(format!(
            "cargo xtask compare on the cyclic variant exited {:?}",
            output.status.code()
        ));
    } else {
        let triage = super::read_json(&cyclic_out.join("triage.json"));
        let report = super::read_json(&cyclic_out.join("report.json"));
        let evaluations = super::read_json(&cyclic_out.join("evaluations.json"));
        every_cell_once(
            &triage,
            &serde_json::from_str(&cyclic_text).unwrap(),
            &mut failures,
        );
        let classes = triaged(&triage);
        let expected: Vec<String> = CLASSES_CALCULATED
            .iter()
            .map(|class| (*class).to_owned())
            .chain(["Calc!C1 not_modeled formula Evaluation:NotModelled root".to_owned()])
            .collect();
        if classes != expected {
            failures.push(format!(
                "the cyclic variant's cells are classed {classes:?}, expected {expected:?}"
            ));
        }
        // Six formula cells: A1 to A3 calculated and matched, B1, B2 and C1 not modelled, no cache
        // counted, and four evaluator calls (A1, A2, B2 and A3; C1 is never evaluated).
        let counted = counts(&report);
        if counted != [6, 3, 3, 0, 0, 0, 3, 0, 0, 4] {
            failures.push(format!(
                "the cyclic variant's report counts are {counted:?}, expected [6, 3, 3, 0, 0, 0, 3, 0, 0, 4]"
            ));
        }
        let a3 = report_cell(&report, "Calc", "A3");
        if a3["verdict"] != "matched" {
            failures.push(format!("the cyclic variant's Calc!A3 verdict is {a3}"));
        }
        if evaluated(&evaluations)
            .iter()
            .any(|entry| entry.starts_with("Calc!R1C3 "))
        {
            failures.push(format!(
                "the cyclic variant's evaluation record holds C1: {:?}",
                evaluated(&evaluations)
            ));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        if !stdout.contains("formula Evaluation:NotModelled: 1 root, blocking 0 cells: Calc!C1") {
            failures.push(format!("the cyclic variant's summary is\n{stdout}"));
        }
        evidence.push(format!(
            "cyclic variant: classes {classes:?}; report counts {counted:?}; Calc!A3 {a3}"
        ));
    }

    // 5. A variant calc-doc refuses (Inputs!A4 is an ISO date cell): every cell is missing with
    // the typed error and classed doc.
    let refused = package(
        &inputs_sheet(r#"<row r="4"><c r="A4" t="d"><v>2026-10-21</v></c></row>"#),
        &calc_sheet(""),
    );
    let refused_text = authored_capture(&refused, &HAND_DERIVED, &[]);
    if let Some((out, _)) = compared(
        "compare-refused",
        &refused,
        &refused_text,
        &dir,
        &mut failures,
    ) {
        let triage = super::read_json(&out.join("triage.json"));
        let report = super::read_json(&out.join("report.json"));
        every_cell_once(
            &triage,
            &serde_json::from_str(&refused_text).unwrap(),
            &mut failures,
        );
        let classes = triaged(&triage);
        if classes.len() != 5
            || !classes
                .iter()
                .all(|cell| cell.ends_with(" missing doc Workbook:Cell:UnsupportedType workbook"))
        {
            failures.push(format!(
                "the refused variant's cells are classed {classes:?}"
            ));
        }
        let reason = report["cells"][0]["reason"].as_str().unwrap_or_default();
        if !reason.starts_with("HostState::open refused the package: the workbook was refused") {
            failures.push(format!("the refused variant's first reason is {reason:?}"));
        }
        if counts(&report) != [5, 0, 0, 0, 0, 0, 0, 5, 0, 0] {
            failures.push(format!(
                "the refused variant's report counts are {:?}",
                counts(&report)
            ));
        }
        evidence.push(format!(
            "refused variant: classes {classes:?}; first reason {reason:?}"
        ));
    }

    // 6. Under --exact-target the host recalculates under that Exact numeric mode and the verdict
    // certifies against that target. calc-func has no Exact arithmetic yet, so the evaluator itself
    // refuses SUM at Calc!A1 with ExactUnavailable: the evaluation record shows the mode the
    // evaluations ran under, not only the command's own account of it, and the key tells the
    // refusal apart from a function the catalogue does not hold.
    let exact_out = dir.join("compare-exact");
    let target = "16.0.20430.20000,current,calc-1,excel-x86-64";
    let output = xtask(
        "compare-exact",
        &[
            "compare",
            "--fixture",
            &fixture.display().to_string(),
            "--capture",
            &capture_path.display().to_string(),
            "--out",
            &exact_out.display().to_string(),
            "--exact-target",
            target,
        ],
        &dir,
    );
    if output.status.code() != Some(0) {
        failures.push(format!(
            "cargo xtask compare --exact-target exited {:?}",
            output.status.code()
        ));
    } else {
        let triage = super::read_json(&exact_out.join("triage.json"));
        let report = super::read_json(&exact_out.join("report.json"));
        let evaluations = super::read_json(&exact_out.join("evaluations.json"));
        every_cell_once(&triage, &capture, &mut failures);
        let a1 = evaluations["evaluations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["sheet"] == "Calc" && entry["row"] == 1 && entry["column"] == 1)
            .map(|entry| entry["returned"].to_string())
            .unwrap_or_default();
        if report["numeric_mode"]["mode"] != "exact"
            || report["numeric_mode"]["excel_build"] != "16.0.20430.20000"
            || triage["run"]["numeric_mode"] != format!("exact {target}")
            || !a1.contains("ExactUnavailable")
        {
            failures.push(format!(
                "under --exact-target the report's numeric mode is {}, the triage's {}, and Calc!A1's evaluation returned {a1}",
                report["numeric_mode"], triage["run"]["numeric_mode"]
            ));
        }
        let classes = triaged(&triage);
        let a1_class = "Calc!A1 not_modeled function-missing ExactUnavailable:SUM root";
        let a1_feature = &report_cell(&report, "Calc", "A1")["feature"];
        if !classes[0].starts_with(a1_class)
            || a1_feature != "Evaluation:Function:ExactUnavailable (SUM)"
        {
            failures.push(format!(
                "under --exact-target Calc!A1 is classed {:?} with feature {a1_feature}, expected {a1_class:?} and Evaluation:Function:ExactUnavailable (SUM)",
                classes[0]
            ));
        }
        evidence.push(format!(
            "--exact-target {target}: classes {classes:?}; Calc!A1's evaluation returned {a1}"
        ));
    }

    // 7. A capture of other bytes is refused, exit 1, and nothing is written.
    let other_out = dir.join("compare-other-bytes");
    let output = compare(
        "compare-other-bytes",
        &cyclic_fixture,
        &capture_path,
        &other_out,
        &dir,
    );
    let stderr = String::from_utf8_lossy(&output.stderr);
    if output.status.code() != Some(1)
        || !stderr.contains("the capture is not of these bytes")
        || other_out.exists()
    {
        failures.push(format!(
            "a capture of other bytes: exit {:?}, output directory written {}, stderr {stderr}",
            output.status.code(),
            other_out.exists()
        ));
    }
    evidence.push(format!(
        "a capture of other bytes: exit {:?}: {}",
        output.status.code(),
        stderr.trim()
    ));
    super::finish(CLASSIFIED, &dir, &evidence, &failures);
}

/// Exit code 4 of `cargo xtask capture`: this host cannot run a capture.
const CAPTURE_UNAVAILABLE: i32 = 4;

/// Whether `cargo xtask capture`'s exit `code` and standard error `stderr` say the capture was
/// refused for its Excel instance's isolation: the worker's refusal of an instance with an add-in
/// open in it (exit 1), or a record whose session carries an isolation failure (exit 5).
fn isolation_refused(code: Option<i32>, stderr: &str) -> bool {
    (code == Some(1) && stderr.contains("this Excel instance is not isolated"))
        || (code == Some(5) && stderr.contains("isolation failure"))
}

/// The body of `dc_kt3l__live_capture`.
pub(super) fn live_capture() {
    registered(LIVE);
    let route = std::env::var(PLATFORM_VARIABLE).unwrap_or_default();
    if route != "excel" {
        println!(
            "ACCEPT-NOT-RUN: {LIVE}: the live capture runs only on the excel route; this run's route is {route:?}, so no Excel was started"
        );
        return;
    }
    let dir = evidence_dir(LIVE);
    let mut evidence = Vec::new();
    let mut failures = Vec::new();
    let book = workbook();
    let fixture = dir.join("workbook.xlsm");
    super::write(&fixture, &book);
    let capture_path = dir.join("capture.json");
    let output = xtask(
        "capture",
        &[
            "capture",
            "--fixture",
            &fixture.display().to_string(),
            "--out",
            &capture_path.display().to_string(),
            "--case",
            LIVE,
            "--work-dir",
            &dir.join("capture-work").display().to_string(),
        ],
        &dir,
    );
    let code = output.status.code();
    let stderr = String::from_utf8_lossy(&output.stderr);
    if code == Some(CAPTURE_UNAVAILABLE) || isolation_refused(code, &stderr) {
        println!(
            "ACCEPT-NOT-RUN: {LIVE}: cargo xtask capture could not take an isolated capture on this host (exit {code:?}): {}",
            super::tail(&output.stderr, 6).replace('\n', " | ")
        );
        return;
    }
    if code != Some(0) {
        failures.push(format!(
            "cargo xtask capture failed on this workbook (exit {code:?}): {}",
            super::tail(&output.stderr, 12)
        ));
        super::finish(LIVE, &dir, &evidence, &failures);
        return;
    }
    let capture = super::read_json(&capture_path);
    evidence.push(format!(
        "capture: {}",
        String::from_utf8_lossy(&output.stdout)
            .lines()
            .filter(|line| line.contains("formula cells") || line.contains("failure ["))
            .collect::<Vec<_>>()
            .join(" | ")
    ));
    // Excel's raw values are the hand-derived ones.
    let observed: Vec<String> = capture["observations"]
        .as_array()
        .unwrap()
        .iter()
        .map(|observation| {
            format!(
                "{}!R{}C{} {}",
                observation["sheet"].as_str().unwrap(),
                observation["row"],
                observation["column"],
                observation["excel_raw"]
            )
        })
        .collect();
    let expected_observed = [
        r#"Calc!R1C1 {"number":"401f000000000000"}"#,
        r#"Calc!R2C1 {"number":"4022800000000000"}"#,
        r#"Calc!R3C1 {"number":"4031000000000000"}"#,
        r#"Calc!R1C2 {"error":"name"}"#,
        r#"Calc!R2C2 {"error":"name"}"#,
    ];
    let mut sorted_observed = observed.clone();
    sorted_observed.sort();
    let mut sorted_expected: Vec<String> =
        expected_observed.iter().map(|s| (*s).to_owned()).collect();
    sorted_expected.sort();
    if sorted_observed != sorted_expected {
        failures.push(format!(
            "Excel observed {observed:?}, the hand-derived values are {expected_observed:?}"
        ));
    }
    evidence.push(format!("Excel observed: {observed:?}"));
    let out = dir.join("compare");
    let output = compare("compare", &fixture, &capture_path, &out, &dir);
    if output.status.code() != Some(0) {
        failures.push(format!(
            "cargo xtask compare exited {:?}: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stderr)
        ));
    } else {
        // The live capture's inventory is Excel's; the triage lists it in its order, so the
        // classes are compared as a set.
        let triage = super::read_json(&out.join("triage.json"));
        every_cell_once(&triage, &capture, &mut failures);
        let mut classes = triaged(&triage);
        classes.sort();
        let mut expected: Vec<String> =
            CLASSES_CALCULATED.iter().map(|s| (*s).to_owned()).collect();
        expected.sort();
        if classes != expected {
            failures.push(format!(
                "the live comparison's cells are classed {classes:?}, expected {expected:?}"
            ));
        }
        let report = super::read_json(&out.join("report.json"));
        let counted = counts(&report);
        if counted[..4] != [5, 3, 3, 0] || counted[8] != 0 {
            failures.push(format!(
                "the live comparison's report counts are {counted:?}"
            ));
        }
        check_features(&report, "the live comparison", &mut failures);
        evidence.push(format!(
            "live comparison: classes {classes:?}; report counts {counted:?}; captured {}; {}",
            report["captured"],
            String::from_utf8_lossy(&output.stdout)
                .lines()
                .find(|line| line.contains("wall time"))
                .unwrap_or_default()
        ));
    }
    super::finish(LIVE, &dir, &evidence, &failures);
}
